def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    # The template is the row with the most non-background cells.
    ref = max(range(h), key=lambda r: sum(x != bg for x in grid[r]))
    positions = [c for c, x in enumerate(grid[ref]) if x != bg]
    lo, hi = min(positions), max(positions)
    pattern = grid[ref][lo:hi + 1]
    marker = next(x for x in counts if x != bg and x not in pattern)

    out = [row[:] for row in grid]
    anchor = len(pattern) // 2
    for r, row in enumerate(grid):
        if r == ref:
            continue
        for c, x in enumerate(row):
            if x == marker:
                start = c - anchor
                for j, value in enumerate(pattern):
                    k = start + j
                    if 0 <= k < w:
                        out[r][k] = value
    return out
